#!/usr/bin/env python3

"""Test script to reproduce the taxfmt template issue."""

import sys
import os
sys.path.insert(0, os.path.join(os.path.dirname(__file__), '.'))

from wikidict.utils import process_templates

def test_taxfmt():
    """Test the taxfmt template processing."""

    # Test cases based on the Wiktionary examples
    test_cases = [
        # Basic case: {{taxfmt|Solidago|genus}}
        ("{{taxfmt|Solidago|genus}}", None),
        # With display text: {{taxfmt|Solidago|genus|Goldenrod}}
        ("{{taxfmt|Solidago|genus|Goldenrod}}", None),
        # Another example
        ("{{taxfmt|Homo sapiens|species}}", None),
    ]

    print("Testing taxfmt template processing...")
    for i, (template, expected) in enumerate(test_cases):
        try:
            result = process_templates("test", template, "en")
            print(f"Test {i+1}: {template}")
            print(f"Result: {result}")
            if expected:
                print(f"Expected: {expected}")
                print(f"Match: {result == expected}")
            print()
        except Exception as e:
            print(f"Test {i+1} FAILED: {template}")
            print(f"Error: {e}")
            print()

if __name__ == "__main__":
    test_taxfmt()

